-- TABLAS FAO
--1)CREAR TABLA FAO ODS 2.C.1
IF OBJECT_ID(N'[L1].L1_FAO_ODS_2C1', N'U') IS NOT NULL
BEGIN
    DROP TABLE [L1].L1_FAO_ODS_2C1;
END
CREATE TABLE [L1].L1_FAO_ODS_2C1
(
  id_L1_fao_ods_2c1 BIGINT PRIMARY KEY IDENTITY(1,1)
, GeoAreaName VARCHAR(5)
, TimePeriod INT
, Valor DECIMAL(15,1)
)
;

